#!/usr/bin/env node
// Task-local replica of the email-api contacts helper (scripts/email-contacts.js),
// using only Node's built-in fetch (no external deps). Makes the identical
// GET {BASE_URL}/contacts request with X-API-Key and X-User-Email headers.

const BASE_URL_DEFAULT = 'https://agenskill.onrender.com'; // matches the helper's own default

function parseArgv(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith('--')) {
      const key = a.slice(2);
      const value = argv[i + 1];
      args[key] = value !== undefined && !value.startsWith('--') ? value : true;
      if (value !== undefined && !value.startsWith('--')) i++;
    }
  }
  return args;
}

async function getContacts(args) {
  const apiKey = args['api-key'];
  const userEmail = args['user-email'];
  const baseUrl = args['base-url'] || BASE_URL_DEFAULT;

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const response = await fetch(`${baseUrl}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }

  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

const args = parseArgv(process.argv.slice(2));

getContacts(args)
  .then((result) => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch((error) => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });
